-- Production contract reconciliation.
-- Forward-only, idempotent restoration of objects verified absent from production.
-- Also hardens compatibility with the live schema where older migrations were partial.

-- Demand capture foundations
CREATE TABLE IF NOT EXISTS public.lead_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), business_id UUID NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
  request_number INT GENERATED ALWAYS AS IDENTITY, lead_id UUID REFERENCES public.leads(id) ON DELETE SET NULL,
  contact_id UUID REFERENCES public.contacts(id) ON DELETE SET NULL, request_type TEXT NOT NULL DEFAULT 'product',
  title TEXT NOT NULL, description TEXT, product_id UUID REFERENCES public.products(id) ON DELETE SET NULL,
  quantity NUMERIC(12,2), location TEXT, budget NUMERIC(12,2), urgency TEXT DEFAULT 'normal',
  status TEXT NOT NULL DEFAULT 'new', assigned_to UUID REFERENCES public.staff(id), attachments JSONB DEFAULT '[]'::jsonb,
  lost_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.quotes ADD COLUMN IF NOT EXISTS lead_id UUID REFERENCES public.leads(id) ON DELETE SET NULL;
ALTER TABLE public.quotes ADD COLUMN IF NOT EXISTS request_id UUID REFERENCES public.lead_requests(id) ON DELETE SET NULL;
ALTER TABLE public.quotes ADD COLUMN IF NOT EXISTS contact_id UUID REFERENCES public.contacts(id) ON DELETE SET NULL;
ALTER TABLE public.quotes ADD COLUMN IF NOT EXISTS assigned_to UUID REFERENCES public.staff(id) ON DELETE SET NULL;
ALTER TABLE public.quotes ADD COLUMN IF NOT EXISTS access_token TEXT;
ALTER TABLE public.quotes ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS public.sales_orders (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_id UUID NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
 order_number INT GENERATED ALWAYS AS IDENTITY,contact_id UUID REFERENCES public.contacts(id) ON DELETE SET NULL,
 lead_id UUID REFERENCES public.leads(id) ON DELETE SET NULL,request_id UUID REFERENCES public.lead_requests(id) ON DELETE SET NULL,
 quote_id UUID REFERENCES public.quotes(id) ON DELETE SET NULL,items JSONB NOT NULL DEFAULT '[]'::jsonb,total NUMERIC(12,2) NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'confirmed',assigned_to UUID REFERENCES public.staff(id) ON DELETE SET NULL,fulfilled_at TIMESTAMPTZ,
 completed_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,cancel_reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.demand_activity(
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_id UUID NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,
 lead_id UUID REFERENCES public.leads(id) ON DELETE SET NULL,actor_staff_id UUID REFERENCES public.staff(id) ON DELETE SET NULL,
 action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id UUID,details JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

CREATE OR REPLACE FUNCTION public.create_lead_request(p_lead_id UUID,p_request_type TEXT,p_title TEXT,p_description TEXT DEFAULT NULL,p_product_id UUID DEFAULT NULL,p_quantity NUMERIC DEFAULT NULL,p_location TEXT DEFAULT NULL,p_budget NUMERIC DEFAULT NULL,p_urgency TEXT DEFAULT 'normal',p_attachments JSONB DEFAULT '[]'::jsonb) RETURNS UUID SECURITY DEFINER SET search_path=public AS $$ DECLARE v_business UUID;v_contact UUID;v_assignee UUID;v_id UUID;v_num INT;v_lead public.leads%ROWTYPE; BEGIN IF p_request_type !~ '^(product|service|inspection|consultation|callback|custom)$' THEN RAISE EXCEPTION 'invalid request type: %',p_request_type; END IF;SELECT * INTO v_lead FROM public.leads WHERE id=p_lead_id;IF v_lead.id IS NULL THEN RAISE EXCEPTION 'lead not found';END IF;v_business:=v_lead.business_id;v_assignee:=COALESCE(v_lead.assigned_to,(SELECT id FROM public.staff WHERE user_id=auth.uid() LIMIT 1));v_contact:=(SELECT c.id FROM public.contacts c WHERE c.lead_id=p_lead_id LIMIT 1);IF NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=v_business) THEN RAISE EXCEPTION 'not a member';END IF;INSERT INTO public.lead_requests(business_id,lead_id,contact_id,request_type,title,description,product_id,quantity,location,budget,urgency,assigned_to,attachments) VALUES(v_business,p_lead_id,v_contact,p_request_type,p_title,p_description,p_product_id,p_quantity,p_location,p_budget,p_urgency,v_assignee,p_attachments) RETURNING id,request_number INTO v_id,v_num;IF EXISTS(SELECT 1 FROM public.leads WHERE id=p_lead_id AND status='new') THEN UPDATE public.leads SET status='contacted',contacted_at=NOW() WHERE id=p_lead_id;END IF;INSERT INTO public.demand_activity(business_id,lead_id,actor_staff_id,action,entity_type,entity_id,details) VALUES(v_business,p_lead_id,v_assignee,'request.created','request',v_id,jsonb_build_object('request_type',p_request_type,'request_number',v_num,'title',p_title));RETURN v_id;END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.create_quote(p_lead_id UUID,p_title TEXT,p_items JSONB DEFAULT '[]'::jsonb,p_request_id UUID DEFAULT NULL,p_subtotal NUMERIC DEFAULT NULL,p_vat NUMERIC DEFAULT 0,p_valid_until TIMESTAMPTZ DEFAULT NULL,p_assigned_to UUID DEFAULT NULL) RETURNS UUID SECURITY DEFINER SET search_path=public AS $$ DECLARE v_business UUID;v_contact UUID;v_id UUID;v_total NUMERIC;v_subtotal NUMERIC;v_lead public.leads%ROWTYPE;BEGIN SELECT * INTO v_lead FROM public.leads WHERE id=p_lead_id;IF v_lead.id IS NULL THEN RAISE EXCEPTION 'lead not found';END IF;v_business:=v_lead.business_id;v_contact:=(SELECT c.id FROM public.contacts c WHERE c.lead_id=p_lead_id LIMIT 1);IF NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=v_business) THEN RAISE EXCEPTION 'not a member';END IF;v_subtotal:=COALESCE(p_subtotal,(SELECT SUM((item->>'quantity')::numeric*(item->>'unit_price')::numeric) FROM jsonb_array_elements(p_items) AS item));v_total:=COALESCE(v_subtotal,0)+COALESCE(p_vat,0);INSERT INTO public.quotes(business_id,quote_number,lead_id,request_id,contact_id,client_name,client_email,title,items,subtotal,vat_amount,total,valid_until,assigned_to,access_token,status) VALUES(v_business,'Q-'||upper(substring(encode(gen_random_bytes(6),'hex') from 1 for 10)),p_lead_id,p_request_id,v_contact,v_lead.full_name,v_lead.email,p_title,p_items,COALESCE(v_subtotal,0),COALESCE(p_vat,0),v_total,p_valid_until,COALESCE(p_assigned_to,(SELECT id FROM public.staff WHERE user_id=auth.uid() LIMIT 1)),encode(gen_random_bytes(24),'hex'),'draft') RETURNING id INTO v_id;RETURN v_id;END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.create_sales_order(p_lead_id UUID DEFAULT NULL,p_request_id UUID DEFAULT NULL,p_quote_id UUID DEFAULT NULL,p_contact_id UUID DEFAULT NULL,p_items JSONB DEFAULT '[]'::jsonb,p_total NUMERIC DEFAULT 0,p_title TEXT DEFAULT NULL,p_assigned_to UUID DEFAULT NULL) RETURNS UUID SECURITY DEFINER SET search_path=public AS $$ DECLARE v_business UUID;v_assignee UUID;v_id UUID;v_num INT;v_lead UUID:=p_lead_id;v_contact UUID:=p_contact_id;BEGIN IF p_quote_id IS NOT NULL THEN SELECT q.business_id,q.assigned_to,q.lead_id,q.request_id,q.contact_id INTO v_business,v_assignee,v_lead,p_request_id,v_contact FROM public.quotes q WHERE q.id=p_quote_id;ELSIF p_request_id IS NOT NULL THEN SELECT l.business_id,COALESCE(l.assigned_to,(SELECT id FROM public.staff WHERE user_id=auth.uid() LIMIT 1)),l.lead_id,l.contact_id INTO v_business,v_assignee,v_lead,v_contact FROM public.lead_requests l WHERE l.id=p_request_id;ELSIF p_lead_id IS NOT NULL THEN SELECT l.business_id,COALESCE(l.assigned_to,(SELECT id FROM public.staff WHERE user_id=auth.uid() LIMIT 1)),l.id INTO v_business,v_assignee,v_lead FROM public.leads l WHERE l.id=p_lead_id;ELSE SELECT s.business_id,s.id INTO v_business,v_assignee FROM public.staff s WHERE s.user_id=auth.uid() LIMIT 1;END IF;IF NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=v_business) THEN RAISE EXCEPTION 'not a member';END IF;IF p_quote_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.quotes WHERE id=p_quote_id AND status='accepted') THEN RAISE EXCEPTION 'quote must be accepted before ordering';END IF;INSERT INTO public.sales_orders(business_id,contact_id,lead_id,request_id,quote_id,items,total,status,assigned_to) VALUES(v_business,v_contact,v_lead,p_request_id,p_quote_id,p_items,p_total,'confirmed',COALESCE(p_assigned_to,v_assignee)) RETURNING id,order_number INTO v_id,v_num;RETURN v_id;END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.get_quote_by_token(p_token TEXT) RETURNS SETOF public.quotes SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN QUERY SELECT q.* FROM public.quotes q WHERE q.access_token=p_token AND(q.expires_at IS NULL OR q.expires_at>NOW());END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.respond_to_quote(p_token TEXT,p_action TEXT) RETURNS public.quotes SECURITY DEFINER SET search_path=public AS $$ DECLARE v_quote public.quotes%ROWTYPE;BEGIN IF p_action NOT IN('accepted','rejected') THEN RAISE EXCEPTION 'invalid action';END IF;SELECT * INTO v_quote FROM public.quotes WHERE access_token=p_token AND(expires_at IS NULL OR expires_at>NOW());IF v_quote.id IS NULL THEN RAISE EXCEPTION 'quote not found or expired';END IF;UPDATE public.quotes SET status=p_action,updated_at=NOW() WHERE id=v_quote.id RETURNING * INTO v_quote;RETURN v_quote;END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.transition_demand(p_entity_id UUID,p_entity_type TEXT,p_new_status TEXT) RETURNS BOOLEAN SECURITY DEFINER SET search_path=public AS $$ DECLARE v_business UUID;BEGIN IF p_entity_type='request' THEN SELECT business_id INTO v_business FROM public.lead_requests WHERE id=p_entity_id;ELSIF p_entity_type='quote' THEN SELECT business_id INTO v_business FROM public.quotes WHERE id=p_entity_id;ELSIF p_entity_type='order' THEN SELECT business_id INTO v_business FROM public.sales_orders WHERE id=p_entity_id;ELSE RAISE EXCEPTION 'unsupported entity type';END IF;IF v_business IS NULL OR NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=v_business) THEN RAISE EXCEPTION 'not authorized';END IF;IF p_entity_type='request' THEN UPDATE public.lead_requests SET status=p_new_status,updated_at=NOW() WHERE id=p_entity_id;ELSIF p_entity_type='quote' THEN UPDATE public.quotes SET status=p_new_status,updated_at=NOW() WHERE id=p_entity_id;ELSE UPDATE public.sales_orders SET status=p_new_status,updated_at=NOW() WHERE id=p_entity_id;END IF;RETURN TRUE;END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.demand_pipeline(p_business UUID) RETURNS JSONB SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=p_business) THEN RETURN '{"authorized":false}'::jsonb;END IF;RETURN jsonb_build_object('requests',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT status,count(*)::int AS count FROM public.lead_requests WHERE business_id=p_business GROUP BY status ORDER BY status)x),'[]'::jsonb),'quotes',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT status,count(*)::int AS count FROM public.quotes WHERE business_id=p_business GROUP BY status ORDER BY status)x),'[]'::jsonb),'orders',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT status,count(*)::int AS count FROM public.sales_orders WHERE business_id=p_business GROUP BY status ORDER BY status)x),'[]'::jsonb));END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.demand_revenue(p_business UUID,p_from TIMESTAMPTZ DEFAULT NOW()-INTERVAL '90 days',p_to TIMESTAMPTZ DEFAULT NOW()) RETURNS JSONB SECURITY DEFINER SET search_path=public AS $$ DECLARE v JSONB;BEGIN IF NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=p_business) THEN RETURN '{"authorized":false}'::jsonb;END IF;SELECT jsonb_build_object('orders',count(*)::int,'revenue',COALESCE(sum(total),0),'from',p_from,'to',p_to) INTO v FROM public.sales_orders WHERE business_id=p_business AND created_at BETWEEN p_from AND p_to AND status NOT IN('cancelled');RETURN v;END;$$ LANGUAGE plpgsql;

-- Currency
CREATE OR REPLACE FUNCTION public.get_exchange_rate(p_from_currency TEXT,p_to_currency TEXT) RETURNS DECIMAL AS $$ DECLARE v_rate DECIMAL;BEGIN IF p_from_currency=p_to_currency THEN RETURN 1;END IF;SELECT rate INTO v_rate FROM public.exchange_rates WHERE base_currency=p_from_currency AND target_currency=p_to_currency AND effective_from<=CURRENT_DATE AND(effective_to IS NULL OR effective_to>=CURRENT_DATE) ORDER BY effective_from DESC LIMIT 1;RETURN COALESCE(v_rate,1);END;$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.convert_currency(p_amount DECIMAL,p_from_currency TEXT,p_to_currency TEXT) RETURNS DECIMAL AS $$ BEGIN RETURN p_amount*public.get_exchange_rate(p_from_currency,p_to_currency);END;$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Capture/learning
CREATE OR REPLACE FUNCTION public.update_leave_balance(p_staff_id UUID,p_leave_type_id UUID,p_days NUMERIC,p_type TEXT DEFAULT 'approve') RETURNS VOID AS $$ BEGIN IF p_type='approve' THEN UPDATE public.leave_balances SET used_days=used_days+p_days,pending_days=GREATEST(pending_days-p_days,0),updated_at=NOW() WHERE staff_id=p_staff_id AND leave_type_id=p_leave_type_id AND year=EXTRACT(YEAR FROM NOW())::INT;ELSIF p_type='reject' THEN UPDATE public.leave_balances SET pending_days=GREATEST(pending_days-p_days,0),updated_at=NOW() WHERE staff_id=p_staff_id AND leave_type_id=p_leave_type_id AND year=EXTRACT(YEAR FROM NOW())::INT;ELSIF p_type='pending' THEN UPDATE public.leave_balances SET pending_days=pending_days+p_days,updated_at=NOW() WHERE staff_id=p_staff_id AND leave_type_id=p_leave_type_id AND year=EXTRACT(YEAR FROM NOW())::INT;END IF;END;$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.increment_saved_search_use(p_search_id UUID) RETURNS VOID AS $$ BEGIN UPDATE public.saved_searches SET use_count=use_count+1,updated_at=NOW() WHERE id=p_search_id;END;$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.increment_user_learning(p_user_id UUID,p_field TEXT) RETURNS VOID AS $$ BEGIN IF p_field='suggestions_accepted' THEN UPDATE public.user_learning SET avg_actions_per_session=avg_actions_per_session+1,updated_at=NOW() WHERE user_id=p_user_id;ELSE UPDATE public.user_learning SET top_features=jsonb_set(COALESCE(top_features,'[]'::JSONB),ARRAY[p_field],to_jsonb((top_features->>p_field)::INT+1)),updated_at=NOW() WHERE user_id=p_user_id;END IF;END;$$ LANGUAGE plpgsql SECURITY DEFINER;
GRANT EXECUTE ON FUNCTION public.update_leave_balance(UUID,UUID,NUMERIC,TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.increment_saved_search_use(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.increment_user_learning(UUID,TEXT) TO authenticated;

-- Auth security
CREATE OR REPLACE FUNCTION public.record_auth_failure(p_identifier TEXT,p_action TEXT,p_max_attempts INTEGER DEFAULT 5,p_window_seconds INTEGER DEFAULT 300,p_lockout_seconds INTEGER DEFAULT 900) RETURNS TABLE(allowed BOOLEAN,attempts INTEGER,retry_after INTEGER) AS $$ DECLARE v_record RECORD;v_now TIMESTAMPTZ:=NOW();v_attempts INTEGER;BEGIN SELECT * INTO v_record FROM public.auth_rate_limits WHERE identifier=p_identifier AND action=p_action;IF NOT FOUND THEN INSERT INTO public.auth_rate_limits(identifier,action,attempts,last_attempted_at) VALUES(p_identifier,p_action,1,v_now);RETURN QUERY SELECT TRUE,1,0::INTEGER;RETURN;END IF;IF v_record.locked_until IS NOT NULL AND v_record.locked_until>v_now THEN RETURN QUERY SELECT FALSE,v_record.attempts,EXTRACT(EPOCH FROM(v_record.locked_until-v_now))::INTEGER;RETURN;END IF;IF v_record.last_attempted_at<v_now-(p_window_seconds||' seconds')::INTERVAL THEN UPDATE public.auth_rate_limits SET attempts=1,last_attempted_at=v_now,locked_until=NULL WHERE identifier=p_identifier AND action=p_action;RETURN QUERY SELECT TRUE,1,0::INTEGER;RETURN;END IF;v_attempts:=v_record.attempts+1;IF v_attempts>=p_max_attempts THEN UPDATE public.auth_rate_limits SET attempts=v_attempts,last_attempted_at=v_now,locked_until=v_now+(p_lockout_seconds||' seconds')::INTERVAL WHERE identifier=p_identifier AND action=p_action;RETURN QUERY SELECT FALSE,v_attempts,p_lockout_seconds;ELSE UPDATE public.auth_rate_limits SET attempts=v_attempts,last_attempted_at=v_now WHERE identifier=p_identifier AND action=p_action;RETURN QUERY SELECT TRUE,v_attempts,0::INTEGER;END IF;END;$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path=public;
CREATE OR REPLACE FUNCTION public.log_security_event(p_event_type TEXT,p_user_id UUID DEFAULT NULL,p_email TEXT DEFAULT NULL,p_ip_address TEXT DEFAULT NULL,p_user_agent TEXT DEFAULT NULL,p_business_id UUID DEFAULT NULL,p_metadata JSONB DEFAULT '{}',p_success BOOLEAN DEFAULT TRUE) RETURNS VOID AS $$ BEGIN IF p_business_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=p_business_id) THEN RETURN;END IF;INSERT INTO public.security_audit_log(event_type,user_id,email,ip_address,user_agent,business_id,metadata,success) VALUES(p_event_type,p_user_id,p_email,p_ip_address,p_user_agent,p_business_id,p_metadata,p_success);END;$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path=public;
GRANT EXECUTE ON FUNCTION public.record_auth_failure(TEXT,TEXT,INTEGER,INTEGER,INTEGER) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.log_security_event(TEXT,UUID,TEXT,TEXT,TEXT,UUID,JSONB,BOOLEAN) TO anon,authenticated;

-- Personal workspace compatibility
ALTER TABLE public.user_pinned_items ADD COLUMN IF NOT EXISTS business_id UUID REFERENCES public.businesses(id) ON DELETE CASCADE;
ALTER TABLE public.user_pinned_items ADD COLUMN IF NOT EXISTS entity_type TEXT;
ALTER TABLE public.user_pinned_items ADD COLUMN IF NOT EXISTS entity_id TEXT;
ALTER TABLE public.user_pinned_items ADD COLUMN IF NOT EXISTS pin_label TEXT;
ALTER TABLE public.user_pinned_items ADD COLUMN IF NOT EXISTS sort_order INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.user_pinned_items ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE OR REPLACE FUNCTION public.my_workspace_arrangement() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT COALESCE((SELECT jsonb_build_object('user_id',s.user_id,'business_id',s.business_id,'selected_tools',COALESCE(ws.selected_tools,'{}'::text[]),'selection_completed',COALESCE(ws.selection_completed,false),'pinned_items',COALESCE((SELECT jsonb_agg(jsonb_build_object('entity_type',pi.entity_type,'entity_id',pi.entity_id,'pin_label',pi.pin_label,'sort_order',pi.sort_order) ORDER BY pi.sort_order) FROM public.user_pinned_items pi WHERE pi.user_id=s.user_id AND pi.business_id=s.business_id),'[]'::jsonb)) FROM public.staff s LEFT JOIN public.user_workspace_selections ws ON ws.user_id=s.user_id AND ws.business_id=s.business_id WHERE s.user_id=auth.uid() AND COALESCE(s.active,true)=true ORDER BY s.created_at ASC LIMIT 1),jsonb_build_object('user_id',auth.uid(),'membership',false,'selected_tools','{}'::text[],'selection_completed',false,'pinned_items','[]'::jsonb)) $$;
GRANT EXECUTE ON FUNCTION public.my_workspace_arrangement() TO authenticated;

-- Platform builder
CREATE TABLE IF NOT EXISTS public.platform_admins(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT NOT NULL UNIQUE,label TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE public.platform_admins ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_platform_admin() RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM public.platform_admins pa JOIN auth.users u ON u.id=auth.uid() WHERE lower(u.email)=lower(pa.email)); $$;
CREATE OR REPLACE FUNCTION public.builder_dashboard() RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$ BEGIN IF NOT public.is_platform_admin() THEN RETURN jsonb_build_object('authorized',false,'onboarding_conversion',NULL,'cross_business_adoption','[]'::JSONB,'sector_module_usage','[]'::JSONB,'data_scope','aggregate_only_no_business_pii');END IF;RETURN jsonb_build_object('authorized',true,'data_scope','aggregate_only_no_business_pii');END;$$;
GRANT EXECUTE ON FUNCTION public.builder_dashboard() TO authenticated;

-- Business search
CREATE OR REPLACE FUNCTION public.business_search(p_query TEXT,p_types TEXT[] DEFAULT NULL,p_limit INT DEFAULT 20) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$ DECLARE v_biz UUID;v_q TEXT;v_lim INT;v_pattern TEXT;v_exact TEXT;v_prefix TEXT;v_per_type INT;v_results JSONB;v_counts JSONB;v_total INT;BEGIN SELECT cs.business_id INTO v_biz FROM public.get_current_staff() cs LIMIT 1;IF v_biz IS NULL THEN RETURN jsonb_build_object('authorized',false,'results','[]'::jsonb,'counts','{}'::jsonb,'total',0,'query','');END IF;v_q:=btrim(COALESCE(p_query,''));IF length(v_q)<2 THEN RETURN jsonb_build_object('authorized',true,'results','[]'::jsonb,'counts','{}'::jsonb,'total',0,'query',v_q);END IF;v_lim:=GREATEST(1,LEAST(COALESCE(p_limit,20),100));v_per_type:=GREATEST(1,v_lim/3);v_pattern:=replace(replace(replace(v_q,'\','\\'),'%','\%'),'_','\_');v_exact:=lower(v_q);v_prefix:=v_pattern||'%';WITH hits AS (SELECT 'staff' type,s.id,s.name title,COALESCE(NULLIF(s.job_title,''),s.role) subtitle,s.email detail,s.created_at,'/app/people' route,CASE WHEN lower(s.name)=v_exact THEN 0 WHEN s.name ILIKE v_prefix ESCAPE '\' THEN 1 ELSE 2 END rank FROM public.staff s WHERE s.business_id=v_biz AND(s.name ILIKE '%'||v_pattern||'%' ESCAPE '\' OR COALESCE(s.email,'') ILIKE '%'||v_pattern||'%' ESCAPE '\') UNION ALL SELECT 'contact',c.id,c.name,COALESCE(c.company,''),COALESCE(c.email,''),c.created_at,'/app/crm',CASE WHEN lower(c.name)=v_exact THEN 0 WHEN c.name ILIKE v_prefix ESCAPE '\' THEN 1 ELSE 2 END FROM public.contacts c WHERE c.business_id=v_biz AND(c.name ILIKE '%'||v_pattern||'%' ESCAPE '\' OR COALESCE(c.email,'') ILIKE '%'||v_pattern||'%' ESCAPE '\') UNION ALL SELECT 'lead',l.id,l.full_name,COALESCE(l.company_name,l.status),COALESCE(l.email,''),l.created_at,'/app/leads',CASE WHEN lower(l.full_name)=v_exact THEN 0 WHEN l.full_name ILIKE v_prefix ESCAPE '\' THEN 1 ELSE 2 END FROM public.leads l WHERE l.business_id=v_biz AND(l.full_name ILIKE '%'||v_pattern||'%' ESCAPE '\' OR COALESCE(l.email,'') ILIKE '%'||v_pattern||'%' ESCAPE '\') UNION ALL SELECT 'task',t.id,t.title,COALESCE(t.status,t.priority),COALESCE(t.status,''),t.created_at,'/app/tasks',CASE WHEN lower(t.title)=v_exact THEN 0 WHEN t.title ILIKE v_prefix ESCAPE '\' THEN 1 ELSE 2 END FROM public.tasks t WHERE t.business_id=v_biz AND t.title ILIKE '%'||v_pattern||'%' ESCAPE '\'),capped AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY type ORDER BY rank,created_at DESC) rn FROM hits) SELECT COALESCE(jsonb_agg(jsonb_build_object('type',type,'id',id,'title',title,'subtitle',subtitle,'detail',detail,'route',route,'created_at',created_at,'rank',rank) ORDER BY rank,created_at DESC),'[]'::jsonb),(SELECT COALESCE(jsonb_object_agg(type,cnt),'{}'::jsonb) FROM(SELECT type,count(*) cnt FROM hits GROUP BY type)x),(SELECT count(*) FROM hits) INTO v_results,v_counts,v_total FROM capped WHERE rn<=v_per_type;RETURN jsonb_build_object('authorized',true,'results',v_results,'counts',v_counts,'total',v_total,'query',v_q);END;$$;
GRANT EXECUTE ON FUNCTION public.business_search(TEXT,TEXT[],INT) TO authenticated;

-- Meetings
CREATE TABLE IF NOT EXISTS public.meeting_captures(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_id UUID NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,meeting_id UUID REFERENCES public.meetings(id) ON DELETE SET NULL,creator_id UUID REFERENCES public.staff(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT,capture_type TEXT NOT NULL DEFAULT 'screen',storage_path TEXT,duration_seconds INT,size_bytes BIGINT,processing_status TEXT NOT NULL DEFAULT 'pending',view_count INT NOT NULL DEFAULT 0,retention_until TIMESTAMPTZ,deleted_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE OR REPLACE FUNCTION public.create_capture(p_title TEXT,p_capture_type TEXT DEFAULT 'screen',p_description TEXT DEFAULT NULL,p_meeting_id UUID DEFAULT NULL) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_staff RECORD;v_capture_id UUID;v_path TEXT;BEGIN SELECT * INTO v_staff FROM public.get_current_staff() LIMIT 1;IF v_staff.business_id IS NULL THEN RETURN jsonb_build_object('error','Not authorized');END IF;v_path:='meetings/capture-'||extract(epoch from now())::bigint::TEXT||'-'||gen_random_uuid()::TEXT;INSERT INTO public.meeting_captures(business_id,title,description,capture_type,storage_path,processing_status,creator_id,meeting_id) VALUES(v_staff.business_id,p_title,p_description,p_capture_type,v_path,'pending',v_staff.id,p_meeting_id) RETURNING id INTO v_capture_id;RETURN jsonb_build_object('capture_id',v_capture_id,'upload_path',v_path);END;$$;
CREATE OR REPLACE FUNCTION public.finalize_recording(p_storage_path TEXT,p_duration_seconds INT DEFAULT NULL,p_size_bytes BIGINT DEFAULT NULL,p_meeting_id UUID DEFAULT NULL,p_capture_id UUID DEFAULT NULL) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_staff RECORD;BEGIN SELECT * INTO v_staff FROM public.get_current_staff() LIMIT 1;IF v_staff.business_id IS NULL THEN RETURN false;END IF;UPDATE public.meeting_media SET processing_status='available',duration_seconds=p_duration_seconds,size_bytes=p_size_bytes WHERE storage_path=p_storage_path AND meeting_id IN(SELECT id FROM public.meetings WHERE business_id=v_staff.business_id);UPDATE public.meeting_captures SET processing_status='available',duration_seconds=p_duration_seconds,size_bytes=p_size_bytes WHERE storage_path=p_storage_path AND business_id=v_staff.business_id;RETURN true;END;$$;
CREATE OR REPLACE FUNCTION public.generate_recording_signed_url(p_storage_path TEXT,p_expires_seconds INT DEFAULT 3600) RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_staff RECORD;BEGIN SELECT * INTO v_staff FROM public.get_current_staff() LIMIT 1;IF v_staff.business_id IS NULL THEN RETURN NULL;END IF;PERFORM 1 FROM public.meeting_media m WHERE m.storage_path=p_storage_path AND m.meeting_id IN(SELECT id FROM public.meetings WHERE business_id=v_staff.business_id);IF NOT FOUND THEN PERFORM 1 FROM public.meeting_captures c WHERE c.storage_path=p_storage_path AND c.business_id=v_staff.business_id;END IF;IF NOT FOUND THEN RETURN NULL;END IF;RETURN p_storage_path;END;$$;
CREATE OR REPLACE FUNCTION public.increment_capture_view(p_capture_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN UPDATE public.meeting_captures SET view_count=view_count+1 WHERE id=p_capture_id AND business_id IN(SELECT business_id FROM public.get_current_staff());END;$$;
CREATE TABLE IF NOT EXISTS public.meeting_chat_messages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),meeting_id UUID NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE,business_id UUID NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,staff_id UUID REFERENCES public.staff(id) ON DELETE SET NULL,guest_token TEXT,guest_name TEXT,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),edited_at TIMESTAMPTZ,CHECK((staff_id IS NOT NULL) OR(guest_token IS NOT NULL)));
CREATE OR REPLACE FUNCTION public.send_meeting_chat_guest(p_meeting_id UUID,p_guest_token TEXT,p_body TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,pg_temp AS $$ DECLARE v_business_id UUID;v_guest_name TEXT;v_id UUID;BEGIN IF p_body IS NULL OR length(trim(p_body))=0 THEN RAISE EXCEPTION 'Message body is required';END IF;SELECT m.business_id INTO v_business_id FROM public.meetings m WHERE m.id=p_meeting_id;IF v_business_id IS NULL THEN RAISE EXCEPTION 'Meeting not found';END IF;SELECT p.guest_name INTO v_guest_name FROM public.meeting_participants p WHERE p.meeting_id=p_meeting_id AND p.guest_token=p_guest_token AND p.status IN('invited','joined','left') LIMIT 1;IF v_guest_name IS NULL THEN RAISE EXCEPTION 'Invalid guest token';END IF;PERFORM set_config('meeting.guest_token',p_guest_token,true);INSERT INTO public.meeting_chat_messages(meeting_id,business_id,guest_token,guest_name,body) VALUES(p_meeting_id,v_business_id,p_guest_token,v_guest_name,trim(p_body)) RETURNING id INTO v_id;RETURN v_id;END;$$;
CREATE OR REPLACE FUNCTION public.send_meeting_chat(p_meeting_id UUID,p_body TEXT) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,pg_temp AS $$ DECLARE v_business_id UUID;v_staff_id UUID;v_id UUID;BEGIN IF p_body IS NULL OR length(trim(p_body))=0 THEN RAISE EXCEPTION 'Message body is required';END IF;SELECT m.business_id INTO v_business_id FROM public.meetings m WHERE m.id=p_meeting_id;IF v_business_id IS NULL THEN RAISE EXCEPTION 'Meeting not found';END IF;SELECT s.id INTO v_staff_id FROM public.get_current_staff() s WHERE s.business_id=v_business_id LIMIT 1;IF v_staff_id IS NULL THEN RAISE EXCEPTION 'Not authorized to chat in this meeting';END IF;INSERT INTO public.meeting_chat_messages(meeting_id,business_id,staff_id,body) VALUES(p_meeting_id,v_business_id,v_staff_id,trim(p_body)) RETURNING id INTO v_id;RETURN v_id;END;$$;
CREATE TABLE IF NOT EXISTS public.meeting_reports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),meeting_id UUID NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE,business_id UUID NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE,generated_by UUID REFERENCES public.staff(id) ON DELETE SET NULL,report_data JSONB NOT NULL,sent_to UUID[] DEFAULT '{}',sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE OR REPLACE FUNCTION public.get_meeting_reports(p_meeting_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_staff RECORD;v_reports JSONB;BEGIN SELECT * INTO v_staff FROM public.get_current_staff() LIMIT 1;IF v_staff.business_id IS NULL THEN RETURN '[]'::jsonb;END IF;SELECT COALESCE(jsonb_agg(jsonb_build_object('id',r.id,'meeting_id',r.meeting_id,'report_data',r.report_data,'sent_to',r.sent_to,'sent_at',r.sent_at,'created_at',r.created_at) ORDER BY r.created_at DESC),'[]'::jsonb) INTO v_reports FROM public.meeting_reports r WHERE r.meeting_id=p_meeting_id AND r.business_id=v_staff.business_id;RETURN v_reports;END;$$;
CREATE OR REPLACE FUNCTION public.generate_meeting_report(p_meeting_id UUID,p_send_notifications BOOLEAN DEFAULT true) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_staff RECORD;v_meeting RECORD;v_summary TEXT;v_report_id UUID;v_report_data JSONB;BEGIN SELECT * INTO v_staff FROM public.get_current_staff() LIMIT 1;SELECT * INTO v_meeting FROM public.meetings WHERE id=p_meeting_id;IF v_meeting.business_id IS NULL OR v_meeting.business_id!=v_staff.business_id THEN RETURN jsonb_build_object('error','Not authorized');END IF;SELECT summary INTO v_summary FROM public.meeting_summaries WHERE meeting_id=p_meeting_id ORDER BY created_at DESC LIMIT 1;v_report_data:=jsonb_build_object('meeting',jsonb_build_object('id',v_meeting.id,'title',v_meeting.title,'date',v_meeting.date,'start_time',v_meeting.start_time,'end_time',v_meeting.end_time,'location',v_meeting.location,'meeting_link',v_meeting.meeting_link),'summary',COALESCE(v_summary,''),'generated_at',NOW(),'generated_by',v_staff.id);INSERT INTO public.meeting_reports(meeting_id,business_id,generated_by,report_data) VALUES(p_meeting_id,v_staff.business_id,v_staff.id,v_report_data) RETURNING id INTO v_report_id;RETURN jsonb_build_object('report_id',v_report_id,'report_data',v_report_data,'notified',0);END;$$;
GRANT EXECUTE ON FUNCTION public.create_capture(TEXT,TEXT,TEXT,UUID) TO authenticated;GRANT EXECUTE ON FUNCTION public.finalize_recording(TEXT,INT,BIGINT,UUID,UUID) TO authenticated;GRANT EXECUTE ON FUNCTION public.generate_recording_signed_url(TEXT,INT) TO authenticated;GRANT EXECUTE ON FUNCTION public.increment_capture_view(UUID) TO authenticated;GRANT EXECUTE ON FUNCTION public.send_meeting_chat_guest(UUID,TEXT,TEXT) TO authenticated;GRANT EXECUTE ON FUNCTION public.send_meeting_chat(UUID,TEXT) TO authenticated;GRANT EXECUTE ON FUNCTION public.generate_meeting_report(UUID,BOOLEAN) TO authenticated;GRANT EXECUTE ON FUNCTION public.get_meeting_reports(UUID) TO authenticated;

-- Other contract objects
ALTER TABLE public.approvals ADD COLUMN IF NOT EXISTS current_step INTEGER;
ALTER TABLE public.approvals ADD COLUMN IF NOT EXISTS total_steps INTEGER;
CREATE OR REPLACE VIEW public.approval_requests WITH (security_barrier=true) AS SELECT a.id,a.business_id,a.status,a.current_step AS current_level,a.total_steps,a.amount,a.entity_type AS type,COALESCE(a.description,a.entity_type) AS entity_name,a.entity_id,a.requester_id,s.full_name AS requester,a.created_at,a.updated_at FROM public.approvals a LEFT JOIN public.staff s ON s.id=a.requester_id;
CREATE OR REPLACE VIEW public.entity_freshness_status WITH (security_barrier=true) AS SELECT id,business_id,entity_type,entity_id,last_event_type,last_event_at,updated_at,CASE WHEN last_event_at IS NULL THEN 'unknown' WHEN now()-last_event_at<interval '1 hour' THEN 'fresh' WHEN now()-last_event_at<interval '24 hours' THEN 'today' WHEN now()-last_event_at<interval '7 days' THEN 'stale' ELSE 'old' END AS freshness_tier,CASE WHEN last_event_at IS NULL THEN NULL ELSE EXTRACT(EPOCH FROM(now()-last_event_at))::INTEGER END AS seconds_since_update FROM public.entity_freshness;

-- Contract-only tenant RPC
CREATE OR REPLACE FUNCTION public.business_relationships(p_business_id UUID,p_start_type TEXT,p_start_id UUID,p_max_depth INTEGER DEFAULT 3) RETURNS TABLE(entity_type TEXT,entity_id UUID,depth INTEGER,path TEXT[]) AS $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.get_current_staff() cs WHERE cs.business_id=p_business_id) THEN RETURN;END IF;RETURN QUERY SELECT * FROM public.recursive_neighbors(p_business_id,p_start_type,p_start_id,p_max_depth);END;$guard$ LANGUAGE plpgsql STABLE SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.my_workspace_arrangement() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT COALESCE((SELECT jsonb_build_object('user_id',s.user_id,'business_id',s.business_id,'selected_tools',COALESCE(ws.selected_tools,'{}'::text[]),'selection_completed',COALESCE(ws.selection_completed,false),'pinned_items',COALESCE((SELECT jsonb_agg(jsonb_build_object('entity_type',pi.entity_type,'entity_id',pi.entity_id,'pin_label',pi.pin_label,'sort_order',pi.sort_order) ORDER BY pi.sort_order) FROM public.user_pinned_items pi WHERE pi.user_id=s.user_id AND pi.business_id=s.business_id),'[]'::jsonb)) FROM public.staff s LEFT JOIN public.user_workspace_selections ws ON ws.user_id=s.user_id AND ws.business_id=s.business_id WHERE s.user_id=auth.uid() AND COALESCE(s.active,true)=true ORDER BY s.created_at ASC LIMIT 1),jsonb_build_object('user_id',auth.uid(),'membership',false,'selected_tools','{}'::text[],'selection_completed',false,'pinned_items','[]'::jsonb)) $$;
GRANT EXECUTE ON FUNCTION public.my_workspace_arrangement() TO authenticated;
